insert into public.email_automations(id,key,name,trigger_type,is_active) values('cc38b0df-a057-5d15-b332-8173827e867c','course_yoga-femininity','Йога плюс женственность','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('yoga-femininity','Йога плюс женственность','course','',90,3,5,'cc38b0df-a057-5d15-b332-8173827e867c','69560e5e8d6ac8a9ef62e1244006e26f3d5dc15f738ebae2a0092dbef4ab73fe') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('c30d3974-3932-590a-92cf-1a0fdbb3419a','cc38b0df-a057-5d15-b332-8173827e867c','Урок 1: Как получить власть над мужчинами',1,0,'Урок 1 {Йога плюс женственность} Как получить власть над мужчинами','{"ru":"Урок 1 {Йога плюс женственность} Как получить власть над мужчинами"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-femininity/yoga-femininity_email-e757bc5b6506.jpg" alt="Йога плюс женственность" width="504" height="187" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решили пройти курс &quot;Йога плюс женственность»!</p><p></p><p>Впереди у Вас месяц практик, преимущественно направленных на гармонизацию второй чакры. И, хотя эта чакра проводит лёгкие, приятные состояния, на ней есть множество энергетических блоков. На уровне психики и поведения они проявляются в виде всевозможных запретительных или побудительных программ, а на уровне тела - в жесткости в области таза и в ряде заболеваний мочеполовой системы.</p><p></p><p>Путь саморазвития очень непрост, так как приходится покидать зону комфорта. Ведь именно то, к чему Вы привыкли, что вам кажется «правильным», и создаёт то, что Вы воспринимаете как «реальность», которую нужно немного изменить в процессе прохождения данного курса.</p><p></p><p>Поэтому не цепляйтесь за то, что Вы уже знаете. Я уверен, что Вы знаете очень много! Вместо этого в каждом уроке старайтесь открывать что-то новое. И не просто - «ну да, я тоже так думаю», а «вау!!!»</p><p></p><p>Проявляйте гибкость не только выполняя асаны, уроки с которыми Вы получите при прохождении данного курса, но также и на уровне ваших чувств и вашего разума.</p><p></p><p>И, прежде чем перейти к первому уроку (ссылка на него находится ниже), ознакомьтесь с небольшой вводной информацией.</p><p></p><p><strong>Расписание:</strong><br>На первой неделе курса Вы получите три урока (интервал между уроками - 2 дня). Далее уроки станут сложней, и Вы будете получать два урока в неделю. Если в какой-то день письмо с уроком не пришло, проверьте папку &quot;Спам&quot;, или &quot;Промоакции&quot; (если у Вас почта в Gmail).</p><p></p><p>Обязательно выполняйте задания каждого урока, чтобы превращать свободно летающую в пространстве информацию в свой личный опыт и знания.</p><p></p><p><strong>Вебинары и ответы на вопросы:</strong><br>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p><strong>Техника безопасности:</strong><br>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу проконтролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p><strong>А теперь к уроку...</strong><br>Есть забавный мультфильм, в котором взрослый, и в общем-то неглупый слон волшебным образом теряет разум при звуках флейты. Аналогичный эффект на мужчин оказывают женщины :)))</p><p></p><p>Под влиянием женщин, мы, мужчины, совершаем весьма странные поступки - развязываем сражения, рискуем работой, бросаем семьи... Ну а если повезёт, то пишем музыку, совершаем подвиги...<br>Что-же нами движет? Если не отмахиваться стандартными фразами, а задуматься, то поиск ответа на этот вопрос приводит к удивительным выводам.</p><p></p><p>Пройдя этот урок и выполнив задание, Вы не только узнаете, как управлять мужчинами, но и откроете в себе что-то новое, развитие чего наполнит Вашу жизнь неожиданными смыслами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly">Перейти к уроку</a></p><p></p><p>Желаю Вам плодотворного прохождения курса!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-femininity/yoga-femininity_email-e757bc5b6506.jpg\" alt=\"Йога плюс женственность\" width=\"504\" height=\"187\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я рад, что вы решили пройти курс &quot;Йога плюс женственность»!</p><p></p><p>Впереди у Вас месяц практик, преимущественно направленных на гармонизацию второй чакры. И, хотя эта чакра проводит лёгкие, приятные состояния, на ней есть множество энергетических блоков. На уровне психики и поведения они проявляются в виде всевозможных запретительных или побудительных программ, а на уровне тела - в жесткости в области таза и в ряде заболеваний мочеполовой системы.</p><p></p><p>Путь саморазвития очень непрост, так как приходится покидать зону комфорта. Ведь именно то, к чему Вы привыкли, что вам кажется «правильным», и создаёт то, что Вы воспринимаете как «реальность», которую нужно немного изменить в процессе прохождения данного курса.</p><p></p><p>Поэтому не цепляйтесь за то, что Вы уже знаете. Я уверен, что Вы знаете очень много! Вместо этого в каждом уроке старайтесь открывать что-то новое. И не просто - «ну да, я тоже так думаю», а «вау!!!»</p><p></p><p>Проявляйте гибкость не только выполняя асаны, уроки с которыми Вы получите при прохождении данного курса, но также и на уровне ваших чувств и вашего разума.</p><p></p><p>И, прежде чем перейти к первому уроку (ссылка на него находится ниже), ознакомьтесь с небольшой вводной информацией.</p><p></p><p><strong>Расписание:</strong><br>На первой неделе курса Вы получите три урока (интервал между уроками - 2 дня). Далее уроки станут сложней, и Вы будете получать два урока в неделю. Если в какой-то день письмо с уроком не пришло, проверьте папку &quot;Спам&quot;, или &quot;Промоакции&quot; (если у Вас почта в Gmail).</p><p></p><p>Обязательно выполняйте задания каждого урока, чтобы превращать свободно летающую в пространстве информацию в свой личный опыт и знания.</p><p></p><p><strong>Вебинары и ответы на вопросы:</strong><br>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p><strong>Техника безопасности:</strong><br>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу проконтролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p><strong>А теперь к уроку...</strong><br>Есть забавный мультфильм, в котором взрослый, и в общем-то неглупый слон волшебным образом теряет разум при звуках флейты. Аналогичный эффект на мужчин оказывают женщины :)))</p><p></p><p>Под влиянием женщин, мы, мужчины, совершаем весьма странные поступки - развязываем сражения, рискуем работой, бросаем семьи... Ну а если повезёт, то пишем музыку, совершаем подвиги...<br>Что-же нами движет? Если не отмахиваться стандартными фразами, а задуматься, то поиск ответа на этот вопрос приводит к удивительным выводам.</p><p></p><p>Пройдя этот урок и выполнив задание, Вы не только узнаете, как управлять мужчинами, но и откроете в себе что-то новое, развитие чего наполнит Вашу жизнь неожиданными смыслами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть первый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#24bd96;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#24bd96;mso-line-height-rule:exactly\">Перейти к уроку</a></p><p></p><p>Желаю Вам плодотворного прохождения курса!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-femininity-header","ty